INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C1','kor',2,2,'u5',1,'바른 말을 사용해야 하는 까닭 — 뜻이 헷갈리는 말을 쓰면 듣는 사람이 다르게 알아들어 오해가 생기므로, 생각을 정확히 전하고 서로 존중하려고 바른 말을 쓰기(남을 놀리는 도구가 아님)',ARRAY['2국01-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C2','kor',2,2,'u5',1,'가리키다와 가르치다 — 손가락 같은 것으로 어떤 것을 짚어 보이는 「가리키다」와 모르는 것을 알도록 알려 주는 「가르치다」를 상황에 맞게 구분해 쓰기',ARRAY['2국01-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C3','kor',2,2,'u5',3,'바라다와 바래다 · 작다와 적다 — 마음으로 원하는 「바라다」와 색이 흐려지는 「바래다」, 크기가 덜한 「작다(↔크다)」와 수나 양이 모자란 「적다(↔많다)」를 문장에 맞게 고르기',ARRAY['2국01-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C4','kor',2,2,'u5',3,'다르다와 틀리다 · 잊어버리다와 잃어버리다 — 서로 같지 않은 「다르다」와 계산·사실이 맞지 않은 「틀리다」, 기억이 지워진 「잊어버리다」와 물건이 없어진 「잃어버리다」를 구분해 문장 만들기',ARRAY['2국01-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C5','kor',2,2,'u5',5,'자신의 생각을 바른 말로 발표하기 — 즐거운 학교생활을 위해 지켜야 할 일과 그와 관련한 생각이나 경험을 정리하고, 바른 말을 쓰는지 스스로 확인하며 연습해 발표하기',ARRAY['2국01-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C6','kor',2,2,'u5',5,'발표하거나 들을 때 주의할 점 — 중요한 내용을 생각하며, 듣는 사람을 바라보며 알맞은 목소리로 발표하고, 들을 때는 중요한 내용과 바른 말 사용을 확인하며 듣기',ARRAY['2국01-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C7','kor',2,2,'u5',7,'시간을 나타내는 말 — 아침·점심·오후·밤, 오늘·내일·작년·올해·내년, 다음 날·봄날처럼 일이 일어난 때를 알려 주는 말을 찾고 써 보기',ARRAY['2국01-01']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C8','kor',2,2,'u5',7,'일이 일어난 차례 파악하기 — 시간을 나타내는 말과 함께 앞의 일 때문에 뒤의 일이 생기는 앞뒤 관계를 살펴 이야기에서 일이 일어난 차례를 찾기(시간 말이 없어도 찾을 수 있음)',ARRAY['2국01-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C9','kor',2,2,'u5',7,'겪은 일을 차례대로 말하기 — 언제·어디에서·누구와 있었던 일인지 정하고 시간을 나타내는 말을 넣어 먼저·그다음·마지막 일을 정리해 듣는 사람을 바라보며 말하기',ARRAY['2국01-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C10','kor',2,2,'u5',9,'글을 읽고 일이 일어난 차례 정리하기 — 「희망을 만든 우편집배원」처럼 시간을 나타내는 말과 인물이 한 일을 짝지어 정리하고, 정리한 차례대로 글의 내용을 간추려 말하기',ARRAY['2국02-03']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C11','kor',2,2,'u5',9,'글의 내용 파악과 낱말 뜻 — 인물의 마음과 한 일, 그 까닭을 글에서 찾아 답하고, 만발·자태·조성처럼 글에 나온 낱말의 뜻을 알아 문장 만들기',ARRAY['2국02-03']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C12','kor',2,2,'u5',11,'바른 말 사용 알리기 — 알릴 바른 말의 뜻을 먼저 확인하고, 때·장소·맡은 역할·방법으로 계획을 세워 읽는 사람의 기분을 생각한 알림 활동을 하고 서로 칭찬하기',ARRAY['2국01-02']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u5-C13','kor',2,2,'u5',11,'소리와 글자가 다른 낱말 — 앞문[암문]·국민[궁민]·분리[불리]·설날[설랄]·줄넘기[줄럼끼]·국물[궁물]·먹는[멍는]처럼 이웃한 소리 때문에 글자와 다르게 소리 나는 낱말을 바르게 읽고 쓰기(기초 다지기)',ARRAY['2국04-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X01','kor',2,'u5',ARRAY['K2-2-u5-C2']::text[],'「가리키다」와 「가르치다」를 헷갈려 알려 줄 때 「가리키다」를 쓴다','손가락으로 짚으면 가리키다, 머리에 넣어 주면 가르치다 — 몸짓으로 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X02','kor',2,'u5',ARRAY['K2-2-u5-C3']::text[],'「바라다」와 「바래다」를 헷갈려 원할 때 「바래」, 색이 흐려질 때 「바라」를 쓴다','「원해」로 바꿔 말이 되면 바라다, 「흐려졌다」로 바꿔 말이 되면 바래다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X03','kor',2,'u5',ARRAY['K2-2-u5-C3']::text[],'「작다」와 「적다」를 헷갈려 크기에 「적다」, 수나 양에 「작다」를 쓴다','반대말로 견주기 — 크다의 반대는 작다, 많다의 반대는 적다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X04','kor',2,'u5',ARRAY['K2-2-u5-C4']::text[],'「다르다」를 써야 할 곳에 「틀리다」를 쓴다(생김새·생각이 같지 않은 것을 틀리다고 함)','「맞지 않다」로 바꿔 말이 되면 틀리다, 「같지 않다」로 바꿔 말이 되면 다르다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X05','kor',2,'u5',ARRAY['K2-2-u5-C4']::text[],'「잊어버리다」와 「잃어버리다」를 헷갈린다','머리에서 사라지면 잊어버리다, 손에서 사라지면 잃어버리다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X06','kor',2,'u5',ARRAY['K2-2-u5-C1','K2-2-u5-C12']::text[],'바른 말을 틀리게 말한 친구를 놀리거나 탓하는 도구로 여긴다','「서로 잘 알아들으려고」 — 부드럽게 알려 주는 말로 바꿔 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X07','kor',2,'u5',ARRAY['K2-2-u5-C1','K2-2-u5-C2','K2-2-u5-C3','K2-2-u5-C4']::text[],'낱말의 뜻은 생각하지 않고 글자 모양이나 소리만 보고 고른다','고른 낱말의 뜻을 먼저 말한 뒤 문장에 넣어 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X08','kor',2,'u5',ARRAY['K2-2-u5-C6']::text[],'발표할 때 떠오르는 생각을 모두 말하거나, 아래를 보며 작은 목소리로 말한다','발표 전 세 손가락 점검 — 중요한 내용 · 바라보기 · 알맞은 목소리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X09','kor',2,'u5',ARRAY['K2-2-u5-C6']::text[],'발표를 들을 때 모두 받아 적으려 하거나 바른 말을 쓰는지 살피지 않는다','들을 때 두 가지만 — 중요한 내용 하나, 바른 말인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X10','kor',2,'u5',ARRAY['K2-2-u5-C5']::text[],'지켜야 할 일과 상관없는 생각이나 경험을 이어 말한다','「왜 지켜야 할까?」에 답이 되는 경험인지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X11','kor',2,'u5',ARRAY['K2-2-u5-C7']::text[],'시간을 나타내는 말과 장소·물건을 나타내는 말을 헷갈린다','「언제?」에 답이 되면 시간을 나타내는 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X12','kor',2,'u5',ARRAY['K2-2-u5-C8','K2-2-u5-C10']::text[],'시간을 나타내는 말만 차례의 단서로 여겨, 시간 말이 없으면 차례를 찾지 못하거나 일의 앞뒤(까닭)를 보지 않는다','「이 일 때문에 무슨 일이 생겼지?」 — 원인이 되는 일이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X13','kor',2,'u5',ARRAY['K2-2-u5-C8','K2-2-u5-C9','K2-2-u5-C10']::text[],'일이 일어난 차례를 뒤섞는다','처음 · 그다음 · 마지막 칸에 일을 하나씩 옮겨 놓아 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X14','kor',2,'u5',ARRAY['K2-2-u5-C10','K2-2-u5-C11']::text[],'글에 없는 내용으로 답하거나 자기 생각을 사실처럼 고른다','「글 어디에 있지?」 하고 그 줄을 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u5-X15','kor',2,'u5',ARRAY['K2-2-u5-C13']::text[],'소리 나는 대로 쓰거나 글자대로 읽어 소리와 글자를 헷갈린다','읽을 때는 [소리]대로, 쓸 때는 글자대로 — 둘을 나란히 적어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_basic#1','kor',2,2,'u5','L01','g2_2_kor_u5_L01_basic','lesson_basic','K2-2-u5-C2',1,'mc','auto','『국어』 139쪽 생각 열기 — 바른 말로 이야기한 사람은?',ARRAY['K2-2-u5-X01','K2-2-u5-X07']::text[],false,'{"seq":1,"concept":"K2-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어』 139쪽 생각 열기 — 바른 말로 이야기한 사람은?","options":[{"t":"「동생들에게 축구를 가르쳐 주었어.」라고 말한 친구","correct":true},{"t":"「동생들에게 축구를 가리켜 주었어.」라고 말한 친구","mis":"K2-2-u5-X01"},{"t":"둘 다 바르게 말했어요","mis":"K2-2-u5-X07"}],"explanation":["가르쳐가 맞아요.","139쪽 생각 열기예요.","축구 방법을 알려 주었어요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"점심시간에 운동장에서 뭐 했어?"},{"who":"가","text":"동생들에게 축구를 가르쳐 주었어."},{"who":"나","text":"동생들에게 축구를 가리켜 주었어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
