INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_basic#3','kor',2,2,'u5','L01','g2_2_kor_u5_L01_basic','lesson_basic','K2-2-u5-C2',1,'mc','auto','손가락으로 어떤 것을 짚어 보일 때 쓰는 말은?',ARRAY['K2-2-u5-X01','K2-2-u5-X07']::text[],false,'{"seq":3,"concept":"K2-2-u5-C2","difficulty":1,"kind":"mc","stem":"손가락으로 어떤 것을 짚어 보일 때 쓰는 말은?","options":[{"t":"가리키다","correct":true},{"t":"가르치다","mis":"K2-2-u5-X01"},{"t":"잃어버리다","mis":"K2-2-u5-X07"}],"explanation":["가리키다예요.","140쪽이에요.","짚어 보일 때 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_basic#4','kor',2,2,'u5','L01','g2_2_kor_u5_L01_basic','lesson_basic','K2-2-u5-C8',1,'mc','auto','「제 꾀에 빠진 당나귀」에서 가장 먼저 일어난 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":4,"concept":"K2-2-u5-C8","difficulty":1,"kind":"mc","stem":"「제 꾀에 빠진 당나귀」에서 가장 먼저 일어난 일은?","options":[{"t":"소금을 싣고 가던 당나귀가 물속에 빠졌어요","correct":true},{"t":"주인이 솜 자루를 등에 실었어요","mis":"K2-2-u5-X13"},{"t":"당나귀가 무거운 짐을 싣고 힘들게 걸어갔어요","mis":"K2-2-u5-X13"}],"explanation":["소금 일이 먼저예요.","141쪽이에요.","그 일 때문에 꾀를 부려요."],"asset":{"type":"passage","lines":["어느 날 소금을 싣고 가던 당나귀는 힘들어 버둥거리다 물속에 빠졌어요.","물에 빠지니 소금이 녹아 짐이 가벼워졌어요. 당나귀는 미소를 지었어요.","다음 날 주인은 솜 자루를 당나귀 등에 실었어요. 당나귀는 꾀를 부려 일부러 물에 빠졌어요.","물을 먹은 솜은 매우 무거워졌어요. 당나귀는 무거운 짐을 싣고 힘들게 걸어갔어요."],"title":"『국어』 141쪽 「제 꾀에 빠진 당나귀」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_basic#5','kor',2,2,'u5','L01','g2_2_kor_u5_L01_basic','lesson_basic','K2-2-u5-C1',2,'mc','auto','『국어』 140쪽 — 지윤이가 민재의 말을 잘못 알아들은 까닭은?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":5,"concept":"K2-2-u5-C1","difficulty":2,"kind":"mc","stem":"『국어』 140쪽 — 지윤이가 민재의 말을 잘못 알아들은 까닭은?","options":[{"t":"민재가 뜻이 헷갈리는 「가리켜」를 썼기 때문이에요","correct":true},{"t":"지윤이가 듣기 싫어서요","mis":"K2-2-u5-X14"},{"t":"민재의 목소리가 작아서요","mis":"K2-2-u5-X14"}],"explanation":["말의 뜻이 헷갈렸어요.","140쪽 예시 답안이에요.","바른 말을 써야 해요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"이 낱말은 뭐야? 가리켜 줘!"},{"who":"지윤","text":"낱말을 가리켜 달라고? 자, 낱말을 가리켰어."},{"who":"민재","text":"뭐 하는 거야? 난 무슨 뜻인지 궁금했는데……."},{"who":"지윤","text":"아! 그러면 낱말의 뜻이 무엇인지 가르쳐 달라고 말해야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_basic#6','kor',2,2,'u5','L01','g2_2_kor_u5_L01_basic','lesson_basic','K2-2-u5-C2',2,'match','auto','「가리키다」와 「가르치다」의 뜻을 이어 보세요.','{}'::text[],false,'{"seq":6,"concept":"K2-2-u5-C2","difficulty":2,"kind":"match","stem":"「가리키다」와 「가르치다」의 뜻을 이어 보세요.","pairs":[{"l":"가리키다","r":"손가락 같은 것으로 어떤 것을 짚어 보이다"},{"l":"가르치다","r":"모르는 것을 알도록 알려 주다"}],"mis":"K2-2-u5-X01","explanation":["짚기와 알려 주기예요.","140쪽 예시 답안이에요.","뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
