INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_basic#8','kor',2,2,'u5','L01','g2_2_kor_u5_L01_basic','lesson_basic','K2-2-u5-C8',2,'mc','auto','당나귀가 일부러 물에 빠진 까닭은?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":8,"concept":"K2-2-u5-C8","difficulty":2,"kind":"mc","stem":"당나귀가 일부러 물에 빠진 까닭은?","options":[{"t":"지난번처럼 짐이 가벼워질 줄 알아서","correct":true},{"t":"목이 말라서","mis":"K2-2-u5-X14"},{"t":"주인이 빠지라고 해서","mis":"K2-2-u5-X14"}],"explanation":["앞의 일 때문이에요.","141쪽이에요.","소금이 녹았던 일이에요."],"asset":{"type":"passage","lines":["어느 날 소금을 싣고 가던 당나귀는 힘들어 버둥거리다 물속에 빠졌어요.","물에 빠지니 소금이 녹아 짐이 가벼워졌어요. 당나귀는 미소를 지었어요.","다음 날 주인은 솜 자루를 당나귀 등에 실었어요. 당나귀는 꾀를 부려 일부러 물에 빠졌어요.","물을 먹은 솜은 매우 무거워졌어요. 당나귀는 무거운 짐을 싣고 힘들게 걸어갔어요."],"title":"『국어』 141쪽 「제 꾀에 빠진 당나귀」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
