INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_challenge#5','kor',2,2,'u5','L01','g2_2_kor_u5_L01_challenge','lesson_challenge','K2-2-u5-C1',3,'ox','auto','친구가 「가리켜 줘」라고 잘못 말하면 크게 웃으며 틀렸다고 놀려야 한다.',ARRAY['K2-2-u5-X06']::text[],false,'{"seq":5,"concept":"K2-2-u5-C1","difficulty":3,"kind":"ox","stem":"친구가 「가리켜 줘」라고 잘못 말하면 크게 웃으며 틀렸다고 놀려야 한다.","answer":"X","reason_options":[{"t":"바른 말은 서로 잘 알아들으려고 쓰는 것이니 부드럽게 알려 줘요","correct":true},{"t":"틀리게 말했으니 놀려도 되니까","mis":"K2-2-u5-X06"}],"mis":"K2-2-u5-X06","explanation":["놀리지 않아요.","지도서 209쪽이에요.","존중하는 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_challenge#6','kor',2,2,'u5','L01','g2_2_kor_u5_L01_challenge','lesson_challenge','K2-2-u5-C8',3,'mc','auto','당나귀 이야기에서 「솜 자루를 실었어요」 바로 다음에 일어난 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":6,"concept":"K2-2-u5-C8","difficulty":3,"kind":"mc","stem":"당나귀 이야기에서 「솜 자루를 실었어요」 바로 다음에 일어난 일은?","options":[{"t":"당나귀가 꾀를 부려 일부러 물에 빠졌어요","correct":true},{"t":"소금이 녹아 짐이 가벼워졌어요","mis":"K2-2-u5-X13"},{"t":"소금을 싣고 가다 물속에 빠졌어요","mis":"K2-2-u5-X13"}],"explanation":["꾀를 부렸어요.","141쪽이에요.","차례를 따라가요."],"asset":{"type":"passage","lines":["어느 날 소금을 싣고 가던 당나귀는 힘들어 버둥거리다 물속에 빠졌어요.","물에 빠지니 소금이 녹아 짐이 가벼워졌어요. 당나귀는 미소를 지었어요.","다음 날 주인은 솜 자루를 당나귀 등에 실었어요. 당나귀는 꾀를 부려 일부러 물에 빠졌어요.","물을 먹은 솜은 매우 무거워졌어요. 당나귀는 무거운 짐을 싣고 힘들게 걸어갔어요."],"title":"『국어』 141쪽 「제 꾀에 빠진 당나귀」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_challenge#7','kor',2,2,'u5','L01','g2_2_kor_u5_L01_challenge','lesson_challenge','K2-2-u5-C8',3,'mc','auto','「제 꾀에 빠진 당나귀」라는 제목과 이어지는 일은?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":7,"concept":"K2-2-u5-C8","difficulty":3,"kind":"mc","stem":"「제 꾀에 빠진 당나귀」라는 제목과 이어지는 일은?","options":[{"t":"꾀를 부려 물에 빠졌다가 솜이 무거워져 더 힘들어졌어요","correct":true},{"t":"주인이 당나귀에게 상을 주었어요","mis":"K2-2-u5-X14"},{"t":"당나귀가 소금을 많이 먹었어요","mis":"K2-2-u5-X14"}],"explanation":["꾀 때문에 힘들어졌어요.","141쪽이에요.","제목의 뜻이에요."],"asset":{"type":"passage","lines":["어느 날 소금을 싣고 가던 당나귀는 힘들어 버둥거리다 물속에 빠졌어요.","물에 빠지니 소금이 녹아 짐이 가벼워졌어요. 당나귀는 미소를 지었어요.","다음 날 주인은 솜 자루를 당나귀 등에 실었어요. 당나귀는 꾀를 부려 일부러 물에 빠졌어요.","물을 먹은 솜은 매우 무거워졌어요. 당나귀는 무거운 짐을 싣고 힘들게 걸어갔어요."],"title":"『국어』 141쪽 「제 꾀에 빠진 당나귀」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_challenge#8','kor',2,2,'u5','L01','g2_2_kor_u5_L01_challenge','lesson_challenge','K2-2-u5-C2',4,'sa','auto','짚어 보일 때는 「가리키다」, 모르는 것을 알려 줄 때는 「○○○다」를 써요. 빈칸 세 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u5-C2","difficulty":4,"kind":"sa","stem":"짚어 보일 때는 「가리키다」, 모르는 것을 알려 줄 때는 「○○○다」를 써요. 빈칸 세 글자를 쓰세요.","answer":["가르치"],"explanation":["가르치예요.","140쪽이에요.","가르치다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_challenge#9','kor',2,2,'u5','L01','g2_2_kor_u5_L01_challenge','lesson_challenge','K2-2-u5-C2',4,'essay','teacher','「가리키다」와 「가르치다」를 하나씩 넣어 오늘 학교에서 있었던 일을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u5-C2","difficulty":4,"kind":"essay","stem":"「가리키다」와 「가르치다」를 하나씩 넣어 오늘 학교에서 있었던 일을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 짝이 창밖의 새를 손가락으로 가리켰다. 나는 짝에게 종이접기 방법을 가르쳐 주었다.","scoring_points":["「가리키다」를 짚어 보이는 뜻으로 썼어요","「가르치다」를 알려 주는 뜻으로 썼어요"]},"explanation":["뜻에 맞게 써요.","140쪽이에요.","두 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L01_challenge#10','kor',2,2,'u5','L01','g2_2_kor_u5_L01_challenge','lesson_challenge','K2-2-u5-C8',4,'essay','teacher','「제 꾀에 빠진 당나귀」에서 일어난 일을 「먼저 – 그러자 – 다음 날 – 그래서」를 넣어 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u5-C8","difficulty":4,"kind":"essay","stem":"「제 꾀에 빠진 당나귀」에서 일어난 일을 「먼저 – 그러자 – 다음 날 – 그래서」를 넣어 차례대로 쓰세요.","answer_guide":{"answer":"예: 먼저 소금을 싣고 가던 당나귀가 물에 빠졌다. 그러자 소금이 녹아 짐이 가벼워졌다. 다음 날 당나귀는 솜을 싣고 일부러 물에 빠졌다. 그래서 솜이 무거워져 힘들게 걸어갔다.","scoring_points":["일어난 차례가 맞아요","이어 주는 말을 넣었어요"]},"explanation":["차례대로 써요.","141쪽 5번이에요.","앞뒤를 이어요."],"asset":{"type":"passage","lines":["어느 날 소금을 싣고 가던 당나귀는 힘들어 버둥거리다 물속에 빠졌어요.","물에 빠지니 소금이 녹아 짐이 가벼워졌어요. 당나귀는 미소를 지었어요.","다음 날 주인은 솜 자루를 당나귀 등에 실었어요. 당나귀는 꾀를 부려 일부러 물에 빠졌어요.","물을 먹은 솜은 매우 무거워졌어요. 당나귀는 무거운 짐을 싣고 힘들게 걸어갔어요."],"title":"『국어』 141쪽 「제 꾀에 빠진 당나귀」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
