INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L03_basic#3','kor',2,2,'u5','L03','g2_2_kor_u5_L03_basic','lesson_basic','K2-2-u5-C3',1,'mc','auto','사진첩의 색이 흐려졌을 때 쓰는 말은?',ARRAY['K2-2-u5-X02','K2-2-u5-X07']::text[],false,'{"seq":3,"concept":"K2-2-u5-C3","difficulty":1,"kind":"mc","stem":"사진첩의 색이 흐려졌을 때 쓰는 말은?","options":[{"t":"바래다","correct":true},{"t":"바라다","mis":"K2-2-u5-X02"},{"t":"가르치다","mis":"K2-2-u5-X07"}],"explanation":["바래다예요.","142쪽 만화예요.","색이 흐려졌어요."],"asset":{"type":"speech","turns":[{"who":"윤재","text":"사진첩 같이 보자."},{"who":"지은","text":"좋아. 근데 사진첩이 바랐네."},{"who":"윤재","text":"사진첩이 바랐다고? 사진첩 색이 흐려졌을 때는 「사진첩이 바랬다」고 말해야 해."},{"who":"지은","text":"가방이 너무 적네."},{"who":"윤재","text":"가방 크기가 작을 때는 「작다」고 말해야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L03_basic#4','kor',2,2,'u5','L03','g2_2_kor_u5_L03_basic','lesson_basic','K2-2-u5-C4',1,'mc','auto','물건을 어디에 흘리고 왔을 때 쓰는 말은?',ARRAY['K2-2-u5-X05','K2-2-u5-X07']::text[],false,'{"seq":4,"concept":"K2-2-u5-C4","difficulty":1,"kind":"mc","stem":"물건을 어디에 흘리고 왔을 때 쓰는 말은?","options":[{"t":"잃어버리다","correct":true},{"t":"잊어버리다","mis":"K2-2-u5-X05"},{"t":"바래다","mis":"K2-2-u5-X07"}],"explanation":["잃어버리다예요.","지도서 212쪽이에요.","물건이 없어졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L03_basic#5','kor',2,2,'u5','L03','g2_2_kor_u5_L03_basic','lesson_basic','K2-2-u5-C3',2,'mc','auto','『국어』 142쪽 — 윤재가 「사진첩이 바랐네.」를 듣고 어리둥절해한 까닭은?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":5,"concept":"K2-2-u5-C3","difficulty":2,"kind":"mc","stem":"『국어』 142쪽 — 윤재가 「사진첩이 바랐네.」를 듣고 어리둥절해한 까닭은?","options":[{"t":"「바라다」의 뜻이 문장에 어울리지 않아서","correct":true},{"t":"사진첩이 무거워서","mis":"K2-2-u5-X14"},{"t":"사진이 너무 많아서","mis":"K2-2-u5-X14"}],"explanation":["바래다가 어울려요.","142쪽 예시 답안이에요.","뜻을 생각해요."],"asset":{"type":"speech","turns":[{"who":"윤재","text":"사진첩 같이 보자."},{"who":"지은","text":"좋아. 근데 사진첩이 바랐네."},{"who":"윤재","text":"사진첩이 바랐다고? 사진첩 색이 흐려졌을 때는 「사진첩이 바랬다」고 말해야 해."},{"who":"지은","text":"가방이 너무 적네."},{"who":"윤재","text":"가방 크기가 작을 때는 「작다」고 말해야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L03_basic#6','kor',2,2,'u5','L03','g2_2_kor_u5_L03_basic','lesson_basic','K2-2-u5-C3',2,'mc','auto','윤재는 「가방이 너무 적네.」를 어떻게 고쳐야 한다고 했나요?',ARRAY['K2-2-u5-X03','K2-2-u5-X07']::text[],false,'{"seq":6,"concept":"K2-2-u5-C3","difficulty":2,"kind":"mc","stem":"윤재는 「가방이 너무 적네.」를 어떻게 고쳐야 한다고 했나요?","options":[{"t":"가방 크기가 작을 때는 「작다」고 말해야 한다고 했어요","correct":true},{"t":"「많다」고 말해야 한다고 했어요","mis":"K2-2-u5-X03"},{"t":"「틀리다」고 말해야 한다고 했어요","mis":"K2-2-u5-X07"}],"explanation":["작다예요.","142쪽 예시 답안이에요.","크기를 말해요."],"asset":{"type":"speech","turns":[{"who":"윤재","text":"사진첩 같이 보자."},{"who":"지은","text":"좋아. 근데 사진첩이 바랐네."},{"who":"윤재","text":"사진첩이 바랐다고? 사진첩 색이 흐려졌을 때는 「사진첩이 바랬다」고 말해야 해."},{"who":"지은","text":"가방이 너무 적네."},{"who":"윤재","text":"가방 크기가 작을 때는 「작다」고 말해야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
