INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L03_challenge#8','kor',2,2,'u5','L03','g2_2_kor_u5_L03_challenge','lesson_challenge','K2-2-u5-C3',4,'sa','auto','「크다」의 반대말은 「작다」, 「많다」의 반대말은 「○다」예요. 빈칸 한 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u5-C3","difficulty":4,"kind":"sa","stem":"「크다」의 반대말은 「작다」, 「많다」의 반대말은 「○다」예요. 빈칸 한 글자를 쓰세요.","answer":["적"],"explanation":["적다예요.","지도서 213쪽이에요.","반대말로 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L03_challenge#9','kor',2,2,'u5','L03','g2_2_kor_u5_L03_challenge','lesson_challenge','K2-2-u5-C4',4,'essay','teacher','『국어』 145쪽 6번 — 「다르다」와 「틀리다」를 하나씩 넣어 문장을 만들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u5-C4","difficulty":4,"kind":"essay","stem":"『국어』 145쪽 6번 — 「다르다」와 「틀리다」를 하나씩 넣어 문장을 만들어 쓰세요.","answer_guide":{"answer":"예: 민수와 영수는 성격이 다르다. 이 문제는 자주 틀리는 문제이다.","scoring_points":["「다르다」를 같지 않다는 뜻으로 썼어요","「틀리다」를 맞지 않다는 뜻으로 썼어요"]},"explanation":["뜻에 맞게요.","145쪽 예시 답안이에요.","두 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L03_challenge#10','kor',2,2,'u5','L03','g2_2_kor_u5_L03_challenge','lesson_challenge','K2-2-u5-C3',4,'essay','teacher','오늘 배운 바른 말 두 개를 넣어 친구를 소개하는 글을 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u5-C3","difficulty":4,"kind":"essay","stem":"오늘 배운 바른 말 두 개를 넣어 친구를 소개하는 글을 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 내 친구는 내가 잃어버린 물건을 잘 찾아 주고 어려운 문제를 잘 가르쳐 줍니다. 착한 내 친구가 정말 자랑스럽습니다.","scoring_points":["바른 말을 두 개 넣었어요","뜻에 맞게 썼어요"]},"explanation":["바른 말로 소개해요.","지도서 213쪽 「자랑스러운 내 친구」예요.","뜻을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L05_basic#1','kor',2,2,'u5','L05','g2_2_kor_u5_L05_basic','lesson_basic','K2-2-u5-C5',1,'mc','auto','『국어』 146쪽 — 즐거운 학교생활을 위해 지켜야 할 일로 알맞은 것은?',ARRAY['K2-2-u5-X10']::text[],false,'{"seq":1,"concept":"K2-2-u5-C5","difficulty":1,"kind":"mc","stem":"『국어』 146쪽 — 즐거운 학교생활을 위해 지켜야 할 일로 알맞은 것은?","options":[{"t":"복도에서 걸어 다니기","correct":true},{"t":"복도에서 뛰어다니기","mis":"K2-2-u5-X10"},{"t":"급식 줄 먼저 서려고 달리기","mis":"K2-2-u5-X10"}],"explanation":["걸어 다녀요.","146쪽이에요.","다치지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"나는 복도에서 걸어 다니자고 이야기하고 싶어. 다른 친구와 부딪치거나 넘어져서 다칠 수 있어."},{"who":"친구 2","text":"나는 생각이 다른 친구의 말도 존중하면 좋겠어. 서로 기분이 상하지 않게 이야기해야 해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
