INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L05_challenge#5','kor',2,2,'u5','L05','g2_2_kor_u5_L05_challenge','lesson_challenge','K2-2-u5-C6',3,'mc','auto','길 찾기 활동에서 도착까지 가는 길로 알맞은 것은?',ARRAY['K2-2-u5-X08','K2-2-u5-X09']::text[],false,'{"seq":5,"concept":"K2-2-u5-C6","difficulty":3,"kind":"mc","stem":"길 찾기 활동에서 도착까지 가는 길로 알맞은 것은?","options":[{"t":"중요한 내용 생각하며 발표 → 바라보며 알맞은 목소리 → 바른 말 확인하며 듣기","correct":true},{"t":"떠오르는 생각 모두 발표 → 작은 목소리 → 모두 쓰며 듣기","mis":"K2-2-u5-X08"},{"t":"바라보며 발표 → 헷갈리는 말 구분하지 않고 듣기","mis":"K2-2-u5-X09"}],"explanation":["바른 길이에요.","148쪽 예시 답안이에요.","말하기와 듣기 모두요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L05_challenge#6','kor',2,2,'u5','L05','g2_2_kor_u5_L05_challenge','lesson_challenge','K2-2-u5-C6',3,'ox','auto','발표할 때는 떠오르는 생각을 모두 말해야 잘한 발표이다.',ARRAY['K2-2-u5-X08']::text[],false,'{"seq":6,"concept":"K2-2-u5-C6","difficulty":3,"kind":"ox","stem":"발표할 때는 떠오르는 생각을 모두 말해야 잘한 발표이다.","answer":"X","reason_options":[{"t":"중요한 내용을 생각하며 정리해서 말해야 듣는 사람이 잘 알아들으니까","correct":true},{"t":"많이 말할수록 좋은 발표니까","mis":"K2-2-u5-X08"}],"mis":"K2-2-u5-X08","explanation":["중요한 내용을 말해요.","148쪽이에요.","정리해서 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L05_challenge#7','kor',2,2,'u5','L05','g2_2_kor_u5_L05_challenge','lesson_challenge','K2-2-u5-C5',3,'mc','auto','친구의 발표를 듣고 고칠 점을 말하는 방법으로 알맞은 것은?',ARRAY['K2-2-u5-X06']::text[],false,'{"seq":7,"concept":"K2-2-u5-C5","difficulty":3,"kind":"mc","stem":"친구의 발표를 듣고 고칠 점을 말하는 방법으로 알맞은 것은?","options":[{"t":"「바른 말을 잘 썼어. 목소리를 조금만 더 크게 하면 좋겠어.」","correct":true},{"t":"「너 발표 정말 못한다.」","mis":"K2-2-u5-X06"},{"t":"「나보다 못했어.」","mis":"K2-2-u5-X06"}],"explanation":["존중하며 말해요.","지도서 217쪽이에요.","좋은 점도 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L05_challenge#8','kor',2,2,'u5','L05','g2_2_kor_u5_L05_challenge','lesson_challenge','K2-2-u5-C6',4,'sa','auto','발표할 때는 듣는 사람을 ○○○○ 알맞은 목소리로 말해요. 빈칸 네 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u5-C6","difficulty":4,"kind":"sa","stem":"발표할 때는 듣는 사람을 ○○○○ 알맞은 목소리로 말해요. 빈칸 네 글자를 쓰세요.","answer":["바라보며"],"explanation":["바라보며예요.","148쪽이에요.","듣는 사람을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L05_challenge#9','kor',2,2,'u5','L05','g2_2_kor_u5_L05_challenge','lesson_challenge','K2-2-u5-C5',4,'essay','teacher','즐거운 학교생활을 위해 지켜야 할 일 하나를 정하고, 그와 관련한 생각이나 경험을 넣어 발표 글을 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u5-C5","difficulty":4,"kind":"essay","stem":"즐거운 학교생활을 위해 지켜야 할 일 하나를 정하고, 그와 관련한 생각이나 경험을 넣어 발표 글을 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 차례대로 줄을 섭시다. 지난번에 친구가 새치기를 해서 서로 다툰 적이 있어요. 차례대로 서면 모두 기분 좋게 기다릴 수 있어요.","scoring_points":["지켜야 할 일이 있어요","관련한 생각이나 경험이 있어요","바른 말로 썼어요"]},"explanation":["정리해서 써요.","147쪽 (2)예요.","바른 말을 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L05_challenge#10','kor',2,2,'u5','L05','g2_2_kor_u5_L05_challenge','lesson_challenge','K2-2-u5-C6',4,'essay','teacher','친구의 발표를 듣고 칭찬할 점과 고칠 점을 하나씩 바른 말로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u5-C6","difficulty":4,"kind":"essay","stem":"친구의 발표를 듣고 칭찬할 점과 고칠 점을 하나씩 바른 말로 쓰세요.","answer_guide":{"answer":"예: 칭찬할 점 — 듣는 사람을 바라보며 또박또박 말했어. / 고칠 점 — 「작다」를 써야 할 곳에 「적다」를 썼으니 다음에는 바꾸면 좋겠어.","scoring_points":["칭찬할 점이 있어요","고칠 점을 부드럽게 말했어요"]},"explanation":["존중하며 말해요.","지도서 217쪽이에요.","동료 평가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L07_basic#1','kor',2,2,'u5','L07','g2_2_kor_u5_L07_basic','lesson_basic','K2-2-u5-C10',1,'mc','auto','세나와 아빠가 행사에 가서 가장 먼저 한 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":1,"concept":"K2-2-u5-C10","difficulty":1,"kind":"mc","stem":"세나와 아빠가 행사에 가서 가장 먼저 한 일은?","options":[{"t":"감자를 캤어요","correct":true},{"t":"업고 달리기를 했어요","mis":"K2-2-u5-X13"},{"t":"버스에서 잠이 들었어요","mis":"K2-2-u5-X13"}],"explanation":["감자 캐기예요.","150쪽 예시 답안이에요.","「가장 먼저」예요."],"asset":{"type":"passage","lines":["일요일 아침, 세나는 아빠와 시골의 「아빠와 함께 추억 만들기」 행사에 갔어요.","가장 먼저 감자밭에서 감자를 조심조심 캤어요.","점심이 되자 캔 감자를 씻어 아궁이에 쪄서 먹었어요.","오후에는 아빠가 아이를 업고 달리는 놀이를 했어요. 모두 응원하자 아빠는 더 빨리 달려 이겼어요.","밤이 되어 돌아오는 버스에서 세나는 「아빠 등에 업히니까 따뜻하고 좋았어요.」라고 말하고 잠이 들었어요."],"title":"『국어』 150~151쪽 「아빠와 함께 추억 만들기」(이규희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
