INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L07_basic#4','kor',2,2,'u5','L07','g2_2_kor_u5_L07_basic','lesson_basic','K2-2-u5-C10',1,'mc','auto','세나가 버스에서 아빠에게 한 말은?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":4,"concept":"K2-2-u5-C10","difficulty":1,"kind":"mc","stem":"세나가 버스에서 아빠에게 한 말은?","options":[{"t":"아빠 등에 업히니까 따뜻하고 좋았다고 했어요","correct":true},{"t":"감자가 맛이 없었다고 했어요","mis":"K2-2-u5-X14"},{"t":"다시는 오기 싫다고 했어요","mis":"K2-2-u5-X14"}],"explanation":["따뜻하고 좋았대요.","150쪽 예시 답안이에요.","이야기 끝부분이에요."],"asset":{"type":"passage","lines":["일요일 아침, 세나는 아빠와 시골의 「아빠와 함께 추억 만들기」 행사에 갔어요.","가장 먼저 감자밭에서 감자를 조심조심 캤어요.","점심이 되자 캔 감자를 씻어 아궁이에 쪄서 먹었어요.","오후에는 아빠가 아이를 업고 달리는 놀이를 했어요. 모두 응원하자 아빠는 더 빨리 달려 이겼어요.","밤이 되어 돌아오는 버스에서 세나는 「아빠 등에 업히니까 따뜻하고 좋았어요.」라고 말하고 잠이 들었어요."],"title":"『국어』 150~151쪽 「아빠와 함께 추억 만들기」(이규희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L07_basic#5','kor',2,2,'u5','L07','g2_2_kor_u5_L07_basic','lesson_basic','K2-2-u5-C7',2,'match','auto','『국어』 151쪽 — 시간을 나타내는 말과 세나가 겪은 일을 이어 보세요.','{}'::text[],false,'{"seq":5,"concept":"K2-2-u5-C7","difficulty":2,"kind":"match","stem":"『국어』 151쪽 — 시간을 나타내는 말과 세나가 겪은 일을 이어 보세요.","pairs":[{"l":"아침","r":"행사에 가서 감자를 캤다"},{"l":"점심","r":"감자를 씻어 아궁이에 쪘다"},{"l":"오후","r":"아빠와 놀이 활동을 했다"},{"l":"밤","r":"버스에서 잠이 들었다"}],"mis":"K2-2-u5-X13","explanation":["때와 일이에요.","151쪽 예시 답안이에요.","차례가 보여요."],"asset":{"type":"passage","lines":["일요일 아침, 세나는 아빠와 시골의 「아빠와 함께 추억 만들기」 행사에 갔어요.","가장 먼저 감자밭에서 감자를 조심조심 캤어요.","점심이 되자 캔 감자를 씻어 아궁이에 쪄서 먹었어요.","오후에는 아빠가 아이를 업고 달리는 놀이를 했어요. 모두 응원하자 아빠는 더 빨리 달려 이겼어요.","밤이 되어 돌아오는 버스에서 세나는 「아빠 등에 업히니까 따뜻하고 좋았어요.」라고 말하고 잠이 들었어요."],"title":"『국어』 150~151쪽 「아빠와 함께 추억 만들기」(이규희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
