INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L07_challenge#9','kor',2,2,'u5','L07','g2_2_kor_u5_L07_challenge','lesson_challenge','K2-2-u5-C9',4,'essay','teacher','시간을 나타내는 말을 세 개 넣어 주말에 겪은 일을 차례대로 세 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u5-C9","difficulty":4,"kind":"essay","stem":"시간을 나타내는 말을 세 개 넣어 주말에 겪은 일을 차례대로 세 문장으로 쓰세요.","answer_guide":{"answer":"예: 토요일 아침에 가족과 산에 갔다. 점심에는 꼭대기에서 김밥을 먹었다. 오후에는 내려와서 계곡에서 물놀이를 했다.","scoring_points":["시간 말이 세 개예요","일이 일어난 차례가 맞아요","겪은 일이에요"]},"explanation":["차례대로 써요.","152~153쪽이에요.","시간 말을 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L07_challenge#10','kor',2,2,'u5','L07','g2_2_kor_u5_L07_challenge','lesson_challenge','K2-2-u5-C10',4,'essay','teacher','「아빠와 함께 추억 만들기」에서 가장 기억에 남는 장면을 고르고, 그 장면 바로 앞에 있었던 일과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u5-C10","difficulty":4,"kind":"essay","stem":"「아빠와 함께 추억 만들기」에서 가장 기억에 남는 장면을 고르고, 그 장면 바로 앞에 있었던 일과 함께 쓰세요.","answer_guide":{"answer":"예: 아빠가 더 빨리 달려 이긴 장면이 기억에 남는다. 그 바로 앞에 모두 큰 소리로 응원했다.","scoring_points":["장면을 골랐어요","바로 앞의 일을 바르게 썼어요"]},"explanation":["앞뒤를 이어요.","150쪽이에요.","일의 앞뒤예요."],"asset":{"type":"passage","lines":["일요일 아침, 세나는 아빠와 시골의 「아빠와 함께 추억 만들기」 행사에 갔어요.","가장 먼저 감자밭에서 감자를 조심조심 캤어요.","점심이 되자 캔 감자를 씻어 아궁이에 쪄서 먹었어요.","오후에는 아빠가 아이를 업고 달리는 놀이를 했어요. 모두 응원하자 아빠는 더 빨리 달려 이겼어요.","밤이 되어 돌아오는 버스에서 세나는 「아빠 등에 업히니까 따뜻하고 좋았어요.」라고 말하고 잠이 들었어요."],"title":"『국어』 150~151쪽 「아빠와 함께 추억 만들기」(이규희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L09_basic#1','kor',2,2,'u5','L09','g2_2_kor_u5_L09_basic','lesson_basic','K2-2-u5-C11',1,'mc','auto','우편집배원의 마음이 쓸쓸했던 까닭은?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":1,"concept":"K2-2-u5-C11","difficulty":1,"kind":"mc","stem":"우편집배원의 마음이 쓸쓸했던 까닭은?","options":[{"t":"시골 마을을 오가는 길이 황량했기 때문이에요","correct":true},{"t":"우편물이 너무 많아서요","mis":"K2-2-u5-X14"},{"t":"날마다 비가 와서요","mis":"K2-2-u5-X14"}],"explanation":["길이 황량했어요.","158쪽 예시 답안이에요.","들꽃조차 없었어요."],"asset":{"type":"passage","lines":["시골 마을로 우편물을 배달하는 우편집배원이 있었어요. 마을로 가는 길은 들꽃조차 없어 늘 쓸쓸했어요.","가을의 어느 날, 우편집배원은 한숨을 쉬며 좋은 수가 없을까 생각했어요.","다음 날부터 마을로 오는 길에 하루도 빠짐없이 들꽃 씨앗을 뿌렸어요.","봄날, 길가에 예쁜 꽃과 향기 진한 들풀이 피어났어요.","일 년이 지난 여름날, 꽃들은 더욱 만발했어요.","우편집배원은 길가에 작은 묘목을 심으며 먼 훗날을 기약했어요."],"title":"『국어』 154~157쪽 「희망을 만든 우편집배원」(김현태) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
