INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L09_challenge#6','kor',2,2,'u5','L09','g2_2_kor_u5_L09_challenge','lesson_challenge','K2-2-u5-C10',3,'mc','auto','「희망을 만든 우편집배원」을 간추린 것으로 알맞은 것은?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":6,"concept":"K2-2-u5-C10","difficulty":3,"kind":"mc","stem":"「희망을 만든 우편집배원」을 간추린 것으로 알맞은 것은?","options":[{"t":"쓸쓸한 길을 오가던 우편집배원이 날마다 씨앗을 뿌려 꽃길을 만들고, 가로수도 심었다.","correct":true},{"t":"우편집배원이 꽃을 사서 마을에 팔았다.","mis":"K2-2-u5-X14"},{"t":"우편집배원이 일을 그만두고 도시로 떠났다.","mis":"K2-2-u5-X14"}],"explanation":["차례대로 간추렸어요.","159쪽 (2)예요.","중요한 일만요."],"asset":{"type":"passage","lines":["시골 마을로 우편물을 배달하는 우편집배원이 있었어요. 마을로 가는 길은 들꽃조차 없어 늘 쓸쓸했어요.","가을의 어느 날, 우편집배원은 한숨을 쉬며 좋은 수가 없을까 생각했어요.","다음 날부터 마을로 오는 길에 하루도 빠짐없이 들꽃 씨앗을 뿌렸어요.","봄날, 길가에 예쁜 꽃과 향기 진한 들풀이 피어났어요.","일 년이 지난 여름날, 꽃들은 더욱 만발했어요.","우편집배원은 길가에 작은 묘목을 심으며 먼 훗날을 기약했어요."],"title":"『국어』 154~157쪽 「희망을 만든 우편집배원」(김현태) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L09_challenge#7','kor',2,2,'u5','L09','g2_2_kor_u5_L09_challenge','lesson_challenge','K2-2-u5-C8',3,'ox','auto','이야기의 차례는 「다음 날」 같은 시간을 나타내는 말이 있을 때만 알 수 있다.',ARRAY['K2-2-u5-X12']::text[],false,'{"seq":7,"concept":"K2-2-u5-C8","difficulty":3,"kind":"ox","stem":"이야기의 차례는 「다음 날」 같은 시간을 나타내는 말이 있을 때만 알 수 있다.","answer":"X","reason_options":[{"t":"씨앗을 뿌렸기 때문에 꽃이 핀 것처럼 일의 앞뒤로도 알 수 있으니까","correct":true},{"t":"시간 말이 없으면 차례를 알 수 없으니까","mis":"K2-2-u5-X12"}],"mis":"K2-2-u5-X12","explanation":["앞뒤로도 알아요.","지도서 221쪽 오개념이에요.","까닭을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L09_challenge#8','kor',2,2,'u5','L09','g2_2_kor_u5_L09_challenge','lesson_challenge','K2-2-u5-C11',4,'sa','auto','꽃이 활짝 다 피는 것을 뜻하는 두 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u5-C11","difficulty":4,"kind":"sa","stem":"꽃이 활짝 다 피는 것을 뜻하는 두 글자 낱말을 쓰세요.","answer":["만발"],"explanation":["만발이에요.","159쪽이에요.","꽃 잔치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L09_challenge#9','kor',2,2,'u5','L09','g2_2_kor_u5_L09_challenge','lesson_challenge','K2-2-u5-C10',4,'essay','teacher','시간을 나타내는 말을 넣어 「희망을 만든 우편집배원」의 내용을 차례대로 간추려 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u5-C10","difficulty":4,"kind":"essay","stem":"시간을 나타내는 말을 넣어 「희망을 만든 우편집배원」의 내용을 차례대로 간추려 쓰세요.","answer_guide":{"answer":"예: 가을의 어느 날, 우편집배원은 쓸쓸한 길 때문에 한숨을 쉬었다. 다음 날부터 길에 들꽃 씨앗을 뿌렸다. 봄날, 길에 꽃이 피었다. 일 년이 지난 여름날, 꽃이 만발했고 우편집배원은 가로수도 심었다.","scoring_points":["시간 말을 넣었어요","차례가 맞아요","중요한 일만 간추렸어요"]},"explanation":["차례대로 간추려요.","159쪽 (2)예요.","시간 말이 도와요."],"asset":{"type":"passage","lines":["시골 마을로 우편물을 배달하는 우편집배원이 있었어요. 마을로 가는 길은 들꽃조차 없어 늘 쓸쓸했어요.","가을의 어느 날, 우편집배원은 한숨을 쉬며 좋은 수가 없을까 생각했어요.","다음 날부터 마을로 오는 길에 하루도 빠짐없이 들꽃 씨앗을 뿌렸어요.","봄날, 길가에 예쁜 꽃과 향기 진한 들풀이 피어났어요.","일 년이 지난 여름날, 꽃들은 더욱 만발했어요.","우편집배원은 길가에 작은 묘목을 심으며 먼 훗날을 기약했어요."],"title":"『국어』 154~157쪽 「희망을 만든 우편집배원」(김현태) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L09_challenge#10','kor',2,2,'u5','L09','g2_2_kor_u5_L09_challenge','lesson_challenge','K2-2-u5-C11',4,'essay','teacher','「만발」, 「자태」, 「조성」 가운데 두 낱말을 골라 문장을 만들어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u5-C11","difficulty":4,"kind":"essay","stem":"「만발」, 「자태」, 「조성」 가운데 두 낱말을 골라 문장을 만들어 쓰세요.","answer_guide":{"answer":"예: 화단에 코스모스가 만발했다. 산꼭대기에서 마을의 웅장한 자태를 보았다.","scoring_points":["낱말 두 개를 썼어요","뜻에 맞게 썼어요"]},"explanation":["뜻에 맞게요.","159쪽 (2)예요.","보기처럼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
