INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L11_challenge#9','kor',2,2,'u5','L11','g2_2_kor_u5_L11_challenge','lesson_challenge','K2-2-u5-C12',4,'essay','teacher','알리고 싶은 바른 말 하나를 골라, 그 뜻과 함께 친구들이 읽고 기분 좋게 따라 할 수 있는 알림 글을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u5-C12","difficulty":4,"kind":"essay","stem":"알리고 싶은 바른 말 하나를 골라, 그 뜻과 함께 친구들이 읽고 기분 좋게 따라 할 수 있는 알림 글을 쓰세요.","answer_guide":{"answer":"예: 「작다」는 크기, 「적다」는 수나 양! 가방이 작고, 밥이 적어요. 우리 반 모두 바르게 써 봐요!","scoring_points":["바른 말과 뜻이 있어요","읽는 사람을 생각했어요"]},"explanation":["뜻을 함께 알려요.","160쪽이에요.","고운 마음도요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_L11_challenge#10','kor',2,2,'u5','L11','g2_2_kor_u5_L11_challenge','lesson_challenge','K2-2-u5-C12',4,'essay','teacher','바른 말 알림 활동 계획을 때, 장소, 맡은 역할, 방법으로 나누어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u5-C12","difficulty":4,"kind":"essay","stem":"바른 말 알림 활동 계획을 때, 장소, 맡은 역할, 방법으로 나누어 쓰세요.","answer_guide":{"answer":"예: 때 — 다음 주 수요일 점심시간 / 장소 — 급식실 앞 / 맡은 역할 — 알림판 들기, 낱말 설명하기, 사진 찍기 / 방법 — 바른 말 카드를 보여 주며 설명하기","scoring_points":["때와 장소가 있어요","역할을 나누었어요","방법이 있어요"]},"explanation":["네 가지를 써요.","160쪽이에요.","구체적으로요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
