INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#11','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C8',2,'mc','auto','『국어』 163쪽 — 윤재네 가족의 하루를 차례대로 바르게 놓은 것은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":11,"concept":"K2-2-u5-C8","difficulty":2,"kind":"mc","stem":"『국어』 163쪽 — 윤재네 가족의 하루를 차례대로 바르게 놓은 것은?","options":[{"t":"아침 공원 도착 → 오전 놀이터 → 점심 도시락 → 오후 식물원","correct":true},{"t":"오전 놀이터 → 아침 공원 도착 → 오후 식물원 → 점심 도시락","mis":"K2-2-u5-X13"},{"t":"점심 도시락 → 오후 식물원 → 아침 공원 도착 → 오전 놀이터","mis":"K2-2-u5-X13"}],"explanation":["아침·오전·점심·오후예요.","163쪽 예시 답안이에요.","시간 말을 따라가요."],"asset":{"type":"passage","lines":["오전에는 공원의 놀이터에서 놀았습니다.","오후에는 식물원에서 다양한 꽃을 구경했습니다.","토요일 아침, 윤재네 가족은 공원에 도착했습니다.","점심에는 미리 준비한 도시락을 맛있게 먹었습니다."],"title":"『국어』 163쪽 2번 (차례가 섞여 있어요)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#12','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C8',2,'mc','auto','「팥죽 할머니와 호랑이」에서 멍석이 호랑이를 만 것 바로 다음에 일어난 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":12,"concept":"K2-2-u5-C8","difficulty":2,"kind":"mc","stem":"「팥죽 할머니와 호랑이」에서 멍석이 호랑이를 만 것 바로 다음에 일어난 일은?","options":[{"t":"지게가 멍석에 말린 호랑이를 짊어졌어요","correct":true},{"t":"할머니가 팥죽을 쑤었어요","mis":"K2-2-u5-X13"},{"t":"할머니가 팥밭을 매고 있었어요","mis":"K2-2-u5-X13"}],"explanation":["말린 호랑이를 짊어져요.","국어활동 67쪽이에요.","앞의 일 다음이에요."],"asset":{"type":"passage","lines":["옛날에 산비탈에서 할머니가 팥밭을 매고 있었어요.","드디어 동짓날이 되었어요. 할머니는 가마솥 가득 팥죽을 쑤었어요.","밤이 되자 호랑이가 할머니 집으로 어슬렁어슬렁 걸어 들어왔어요.","멍석이 마당에서 데굴데굴 구르는 호랑이를 뚜르르 말았어요.","지게가 멍석에 말린 호랑이를 짊어졌어요."],"title":"『국어활동』 66~67쪽 「팥죽 할머니와 호랑이」에서 일어난 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
