INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#19','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C11',3,'mc','auto','우편집배원이 날마다 한 일로 길이 어떻게 되었나요?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":19,"concept":"K2-2-u5-C11","difficulty":3,"kind":"mc","stem":"우편집배원이 날마다 한 일로 길이 어떻게 되었나요?","options":[{"t":"쓸쓸하던 길이 즐거운 꽃길이 되었어요","correct":true},{"t":"길이 더 쓸쓸해졌어요","mis":"K2-2-u5-X14"},{"t":"마을 사람들이 떠났어요","mis":"K2-2-u5-X14"}],"explanation":["꽃길이 되었어요.","157쪽이에요.","희망을 만들었어요."],"asset":{"type":"passage","lines":["시골 마을로 우편물을 배달하는 우편집배원이 있었어요. 마을로 가는 길은 들꽃조차 없어 늘 쓸쓸했어요.","가을의 어느 날, 우편집배원은 한숨을 쉬며 좋은 수가 없을까 생각했어요.","다음 날부터 마을로 오는 길에 하루도 빠짐없이 들꽃 씨앗을 뿌렸어요.","봄날, 길가에 예쁜 꽃과 향기 진한 들풀이 피어났어요.","일 년이 지난 여름날, 꽃들은 더욱 만발했어요.","우편집배원은 길가에 작은 묘목을 심으며 먼 훗날을 기약했어요."],"title":"『국어』 154~157쪽 「희망을 만든 우편집배원」(김현태) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#20','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C5',3,'mc','auto','바른 말로 발표하기 위해 발표 전에 할 일로 알맞은 것은?',ARRAY['K2-2-u5-X08']::text[],false,'{"seq":20,"concept":"K2-2-u5-C5","difficulty":3,"kind":"mc","stem":"바른 말로 발표하기 위해 발표 전에 할 일로 알맞은 것은?","options":[{"t":"정리한 글을 다시 읽으며 헷갈리는 말이 없는지 확인해요","correct":true},{"t":"정리 없이 바로 말해요","mis":"K2-2-u5-X08"},{"t":"글자 수를 세어요","mis":"K2-2-u5-X08"}],"explanation":["다시 확인해요.","지도서 217쪽이에요.","바른 말인지요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#21','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C4',3,'ox','auto','「나와 형은 생김새가 조금 다릅니다.」는 바른 문장이다.',ARRAY['K2-2-u5-X04']::text[],false,'{"seq":21,"concept":"K2-2-u5-C4","difficulty":3,"kind":"ox","stem":"「나와 형은 생김새가 조금 다릅니다.」는 바른 문장이다.","answer":"O","reason_options":[{"t":"생김새가 서로 같지 않으니 「다르다」가 맞으니까","correct":true},{"t":"형제는 생김새가 틀려야 하니까","mis":"K2-2-u5-X04"}],"mis":"K2-2-u5-X04","explanation":["다릅니다가 맞아요.","145쪽 예시 답안이에요.","같지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#22','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C9',3,'mc','auto','겪은 일을 차례대로 말한 것으로 알맞은 것은?',ARRAY['K2-2-u5-X13','K2-2-u5-X12']::text[],false,'{"seq":22,"concept":"K2-2-u5-C9","difficulty":3,"kind":"mc","stem":"겪은 일을 차례대로 말한 것으로 알맞은 것은?","options":[{"t":"「아침에 일어나 세수를 했어. 점심에는 친구와 공을 찼어. 저녁에는 일기를 썼어.」","correct":true},{"t":"「저녁에 일기를 썼어. 아침에 세수를 했어. 점심에 공을 찼어.」","mis":"K2-2-u5-X13"},{"t":"「공을 찼어. 일기를 썼어. 세수를 했어.」","mis":"K2-2-u5-X12"}],"explanation":["차례대로예요.","153쪽이에요.","시간 말이 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#23','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C3',4,'sa','auto','「크다」의 반대말은 「작다」, 「많다」의 반대말은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u5-C3","difficulty":4,"kind":"sa","stem":"「크다」의 반대말은 「작다」, 「많다」의 반대말은 무엇인가요? 두 글자로 쓰세요.","answer":["적다"],"explanation":["적다예요.","지도서 213쪽이에요.","양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#24','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C4',4,'essay','teacher','지도서 234~235쪽 평가 — 「다르다」, 「틀리다」, 「잃어버리다」, 「잊어버리다」 가운데 두 낱말을 넣어 자신이 경험한 일을 친구에게 소개하는 글을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u5-C4","difficulty":4,"kind":"essay","stem":"지도서 234~235쪽 평가 — 「다르다」, 「틀리다」, 「잃어버리다」, 「잊어버리다」 가운데 두 낱말을 넣어 자신이 경험한 일을 친구에게 소개하는 글을 쓰세요.","answer_guide":{"answer":"예: 어제 도서관에서 책을 잃어버렸어. 그런데 책 제목도 잊어버려서 찾기가 어려웠어.","scoring_points":["두 낱말을 넣었어요","뜻에 맞게 썼어요","경험한 일이에요"]},"explanation":["바른 말로 소개해요.","지도서 234쪽이에요.","뜻을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_a#25','kor',2,2,'u5','','g2_2_kor_u5_review_a','unit_review','K2-2-u5-C9',4,'essay','teacher','지도서 236~237쪽 평가 — 시간을 나타내는 말을 넣어 자신이 겪은 일을 일이 일어난 차례대로 세 문장 이상 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u5-C9","difficulty":4,"kind":"essay","stem":"지도서 236~237쪽 평가 — 시간을 나타내는 말을 넣어 자신이 겪은 일을 일이 일어난 차례대로 세 문장 이상 쓰세요.","answer_guide":{"answer":"예: 일요일 아침에 동생과 자전거를 탔다. 점심에는 할머니 댁에서 국수를 먹었다. 저녁에는 가족과 보드게임을 했다.","scoring_points":["시간 말을 넣었어요","차례가 맞아요","세 문장 이상이에요"]},"explanation":["차례대로 써요.","지도서 236쪽이에요.","시간 말이 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
