INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_b#11','kor',2,2,'u5','','g2_2_kor_u5_review_b','unit_review','K2-2-u5-C8',2,'mc','auto','『국어활동』 66쪽 — 「팥죽 할머니와 호랑이」에서 「동짓날」 다음에 일어난 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":11,"concept":"K2-2-u5-C8","difficulty":2,"kind":"mc","stem":"『국어활동』 66쪽 — 「팥죽 할머니와 호랑이」에서 「동짓날」 다음에 일어난 일은?","options":[{"t":"밤이 되자 호랑이가 할머니 집으로 들어왔어요.","correct":true},{"t":"할머니가 팥밭을 매고 있었어요.","mis":"K2-2-u5-X13"},{"t":"지게가 호랑이를 짊어졌어요.","mis":"K2-2-u5-X13"}],"explanation":["밤이 되자예요.","국어활동 66쪽 예시 답안이에요.","차례예요."],"asset":{"type":"passage","lines":["옛날에 산비탈에서 할머니가 팥밭을 매고 있었어요.","드디어 동짓날이 되었어요. 할머니는 가마솥 가득 팥죽을 쑤었어요.","밤이 되자 호랑이가 할머니 집으로 어슬렁어슬렁 걸어 들어왔어요.","멍석이 마당에서 데굴데굴 구르는 호랑이를 뚜르르 말았어요.","지게가 멍석에 말린 호랑이를 짊어졌어요."],"title":"『국어활동』 66~67쪽 「팥죽 할머니와 호랑이」에서 일어난 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
