INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_b#19','kor',2,2,'u5','','g2_2_kor_u5_review_b','unit_review','K2-2-u5-C11',3,'mc','auto','우편집배원이 지루해도 일을 그만두지 않은 까닭은?',ARRAY['K2-2-u5-X14']::text[],false,'{"seq":19,"concept":"K2-2-u5-C11","difficulty":3,"kind":"mc","stem":"우편집배원이 지루해도 일을 그만두지 않은 까닭은?","options":[{"t":"설레는 마음으로 우편물을 기다리는 마을 사람들 때문에","correct":true},{"t":"돈을 많이 받아서","mis":"K2-2-u5-X14"},{"t":"길이 아름다워서","mis":"K2-2-u5-X14"}],"explanation":["마을 사람들 때문이에요.","154쪽이에요.","글에 있어요."],"asset":{"type":"passage","lines":["시골 마을로 우편물을 배달하는 우편집배원이 있었어요. 마을로 가는 길은 들꽃조차 없어 늘 쓸쓸했어요.","가을의 어느 날, 우편집배원은 한숨을 쉬며 좋은 수가 없을까 생각했어요.","다음 날부터 마을로 오는 길에 하루도 빠짐없이 들꽃 씨앗을 뿌렸어요.","봄날, 길가에 예쁜 꽃과 향기 진한 들풀이 피어났어요.","일 년이 지난 여름날, 꽃들은 더욱 만발했어요.","우편집배원은 길가에 작은 묘목을 심으며 먼 훗날을 기약했어요."],"title":"『국어』 154~157쪽 「희망을 만든 우편집배원」(김현태) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_b#20','kor',2,2,'u5','','g2_2_kor_u5_review_b','unit_review','K2-2-u5-C6',3,'mc','auto','친구 발표의 고칠 점을 말하는 방법으로 알맞은 것은?',ARRAY['K2-2-u5-X06']::text[],false,'{"seq":20,"concept":"K2-2-u5-C6","difficulty":3,"kind":"mc","stem":"친구 발표의 고칠 점을 말하는 방법으로 알맞은 것은?","options":[{"t":"「「틀리다」 대신 「다르다」를 쓰면 더 좋겠어.」","correct":true},{"t":"「넌 맨날 틀려.」","mis":"K2-2-u5-X06"},{"t":"「다시는 발표하지 마.」","mis":"K2-2-u5-X06"}],"explanation":["부드럽게요.","지도서 217쪽이에요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_b#21','kor',2,2,'u5','','g2_2_kor_u5_review_b','unit_review','K2-2-u5-C3',3,'ox','auto','「내 컵이 선생님 컵보다 작다.」는 바른 문장이다.',ARRAY['K2-2-u5-X03']::text[],false,'{"seq":21,"concept":"K2-2-u5-C3","difficulty":3,"kind":"ox","stem":"「내 컵이 선생님 컵보다 작다.」는 바른 문장이다.","answer":"O","reason_options":[{"t":"컵의 크기를 견주었으니 「작다」가 맞으니까","correct":true},{"t":"양이 모자랄 때도 작다를 쓰니까","mis":"K2-2-u5-X03"}],"mis":"K2-2-u5-X03","explanation":["크기예요.","지도서 215쪽 자료예요.","작다가 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_b#22','kor',2,2,'u5','','g2_2_kor_u5_review_b','unit_review','K2-2-u5-C7',3,'mc','auto','『국어활동』 67쪽 — 「밤」을 넣어 짧은 글을 바르게 쓴 것은?',ARRAY['K2-2-u5-X13','K2-2-u5-X11']::text[],false,'{"seq":22,"concept":"K2-2-u5-C7","difficulty":3,"kind":"mc","stem":"『국어활동』 67쪽 — 「밤」을 넣어 짧은 글을 바르게 쓴 것은?","options":[{"t":"밤이 되자 하늘에 별이 하나둘 뜨기 시작했습니다.","correct":true},{"t":"밤 공원에 갔다 아침 먹었다.","mis":"K2-2-u5-X13"},{"t":"별이 밤입니다.","mis":"K2-2-u5-X11"}],"explanation":["밤이 되자예요.","국어활동 67쪽 예시 답안이에요.","시간 말을 넣었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_b#23','kor',2,2,'u5','','g2_2_kor_u5_review_b','unit_review','K2-2-u5-C2',4,'sa','auto','모르는 것을 알도록 알려 주는 것을 뜻하는 낱말을 「~다」 꼴로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u5-C2","difficulty":4,"kind":"sa","stem":"모르는 것을 알도록 알려 주는 것을 뜻하는 낱말을 「~다」 꼴로 쓰세요.","answer":["가르치다"],"explanation":["가르치다예요.","140쪽이에요.","알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_b#24','kor',2,2,'u5','','g2_2_kor_u5_review_b','unit_review','K2-2-u5-C3',4,'essay','teacher','「바라다」와 「바래다」를 하나씩 넣어 두 문장을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u5-C3","difficulty":4,"kind":"essay","stem":"「바라다」와 「바래다」를 하나씩 넣어 두 문장을 쓰세요.","answer_guide":{"answer":"예: 내일 날씨가 맑기를 바란다. 오래된 사진이 누렇게 바랬다.","scoring_points":["「바라다」를 원하는 뜻으로 썼어요","「바래다」를 흐려지는 뜻으로 썼어요"]},"explanation":["뜻에 맞게요.","143쪽이에요.","두 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_b#25','kor',2,2,'u5','','g2_2_kor_u5_review_b','unit_review','K2-2-u5-C8',4,'essay','teacher','「팥죽 할머니와 호랑이」에서 일어난 일을 차례대로 세 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u5-C8","difficulty":4,"kind":"essay","stem":"「팥죽 할머니와 호랑이」에서 일어난 일을 차례대로 세 가지 쓰세요.","answer_guide":{"answer":"예: 옛날에 할머니가 팥밭을 매고 있었다. 동짓날 할머니는 팥죽을 쑤었다. 밤이 되자 호랑이가 할머니 집으로 들어왔다.","scoring_points":["일이 세 가지예요","차례가 맞아요"]},"explanation":["차례대로요.","국어활동 66~67쪽이에요.","시간 말을 봐요."],"asset":{"type":"passage","lines":["옛날에 산비탈에서 할머니가 팥밭을 매고 있었어요.","드디어 동짓날이 되었어요. 할머니는 가마솥 가득 팥죽을 쑤었어요.","밤이 되자 호랑이가 할머니 집으로 어슬렁어슬렁 걸어 들어왔어요.","멍석이 마당에서 데굴데굴 구르는 호랑이를 뚜르르 말았어요.","지게가 멍석에 말린 호랑이를 짊어졌어요."],"title":"『국어활동』 66~67쪽 「팥죽 할머니와 호랑이」에서 일어난 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_c#1','kor',2,2,'u5','','g2_2_kor_u5_review_c','unit_review','K2-2-u5-C2',1,'mc','auto','『국어활동』 60쪽 — 바르게 말한 것은?',ARRAY['K2-2-u5-X01','K2-2-u5-X07']::text[],false,'{"seq":1,"concept":"K2-2-u5-C2","difficulty":1,"kind":"mc","stem":"『국어활동』 60쪽 — 바르게 말한 것은?","options":[{"t":"선생님께서 국어를 가르쳐 주십니다.","correct":true},{"t":"선생님께서 국어를 가리켜 주십니다.","mis":"K2-2-u5-X01"},{"t":"선생님께서 국어를 잃어버리십니다.","mis":"K2-2-u5-X07"}],"explanation":["가르쳐 주셔요.","국어활동 60쪽 예시 답안이에요.","알려 주셔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_c#2','kor',2,2,'u5','','g2_2_kor_u5_review_c','unit_review','K2-2-u5-C4',1,'mc','auto','『국어활동』 59쪽 — 「2학년 때는 수정이와 ( ) 반이라 아쉽네.」',ARRAY['K2-2-u5-X04','K2-2-u5-X03']::text[],false,'{"seq":2,"concept":"K2-2-u5-C4","difficulty":1,"kind":"mc","stem":"『국어활동』 59쪽 — 「2학년 때는 수정이와 ( ) 반이라 아쉽네.」","options":[{"t":"다른","correct":true},{"t":"틀린","mis":"K2-2-u5-X04"},{"t":"적은","mis":"K2-2-u5-X03"}],"explanation":["다른이에요.","국어활동 58쪽 예시 답안이에요.","같지 않은 반이에요."],"asset":{"type":"passage","lines":["월요일 아침, 은호는 수정이와 함께 즐겁게 학교에 갔습니다.","「수정아! 가방이 무겁니? 내가 도와줄까?」","「내가 교실 앞까지 바래다줄까?」 「아니야, 조금만 더 가면 되는데 뭘.」","「2학년 때는 수정이와 다른 반이라 아쉽네.」","「1학년 때는 반이 같아서 좋았는데…….」"],"title":"『국어활동』 58~59쪽 「학교 가는 길」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
