INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_c#11','kor',2,2,'u5','','g2_2_kor_u5_review_c','unit_review','K2-2-u5-C10',2,'mc','auto','「희망을 만든 우편집배원」에서 「봄날」에 일어난 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":11,"concept":"K2-2-u5-C10","difficulty":2,"kind":"mc","stem":"「희망을 만든 우편집배원」에서 「봄날」에 일어난 일은?","options":[{"t":"길가에 핀 꽃과 들풀 향기를 맡았어요","correct":true},{"t":"들꽃 씨앗을 처음 뿌렸어요","mis":"K2-2-u5-X13"},{"t":"한숨을 쉬었어요","mis":"K2-2-u5-X13"}],"explanation":["꽃향기를 맡았어요.","159쪽이에요.","봄날이에요."],"asset":{"type":"passage","lines":["시골 마을로 우편물을 배달하는 우편집배원이 있었어요. 마을로 가는 길은 들꽃조차 없어 늘 쓸쓸했어요.","가을의 어느 날, 우편집배원은 한숨을 쉬며 좋은 수가 없을까 생각했어요.","다음 날부터 마을로 오는 길에 하루도 빠짐없이 들꽃 씨앗을 뿌렸어요.","봄날, 길가에 예쁜 꽃과 향기 진한 들풀이 피어났어요.","일 년이 지난 여름날, 꽃들은 더욱 만발했어요.","우편집배원은 길가에 작은 묘목을 심으며 먼 훗날을 기약했어요."],"title":"『국어』 154~157쪽 「희망을 만든 우편집배원」(김현태) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
