INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_c#23','kor',2,2,'u5','','g2_2_kor_u5_review_c','unit_review','K2-2-u5-C13',4,'sa','auto','「국민」은 [○민]으로 소리 나요. 빈칸 한 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u5-C13","difficulty":4,"kind":"sa","stem":"「국민」은 [○민]으로 소리 나요. 빈칸 한 글자를 쓰세요.","answer":["궁"],"explanation":["[궁민]이에요.","164쪽이에요.","ㄱ이 ㅇ으로 소리 나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_c#24','kor',2,2,'u5','','g2_2_kor_u5_review_c','unit_review','K2-2-u5-C1',4,'essay','teacher','친구가 「다르다」를 써야 할 곳에 「틀리다」를 썼어요. 친구가 기분 상하지 않게 바른 말을 알려 주는 말을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u5-C1","difficulty":4,"kind":"essay","stem":"친구가 「다르다」를 써야 할 곳에 「틀리다」를 썼어요. 친구가 기분 상하지 않게 바른 말을 알려 주는 말을 쓰세요.","answer_guide":{"answer":"예: 「생각이 같지 않을 때는 「틀리다」보다 「다르다」를 쓰면 더 좋아. 나도 전에 헷갈렸어.」","scoring_points":["바른 말을 알려 주었어요","친구의 기분을 생각했어요"]},"explanation":["부드럽게 알려 줘요.","지도서 209쪽이에요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_c#25','kor',2,2,'u5','','g2_2_kor_u5_review_c','unit_review','K2-2-u5-C10',4,'essay','teacher','「희망을 만든 우편집배원」을 읽고 일이 일어난 차례대로 내용을 간추리고, 가장 인상 깊은 일을 한 문장 더 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u5-C10","difficulty":4,"kind":"essay","stem":"「희망을 만든 우편집배원」을 읽고 일이 일어난 차례대로 내용을 간추리고, 가장 인상 깊은 일을 한 문장 더 쓰세요.","answer_guide":{"answer":"예: 쓸쓸한 길을 오가던 우편집배원이 다음 날부터 씨앗을 뿌렸고, 봄날 꽃이 피고 일 년 뒤 여름날 꽃이 만발했다. 나는 하루도 빠짐없이 씨앗을 뿌린 일이 가장 인상 깊다.","scoring_points":["차례대로 간추렸어요","인상 깊은 일이 있어요"]},"explanation":["간추리고 생각을 더해요.","159쪽이에요.","차례가 중요해요."],"asset":{"type":"passage","lines":["시골 마을로 우편물을 배달하는 우편집배원이 있었어요. 마을로 가는 길은 들꽃조차 없어 늘 쓸쓸했어요.","가을의 어느 날, 우편집배원은 한숨을 쉬며 좋은 수가 없을까 생각했어요.","다음 날부터 마을로 오는 길에 하루도 빠짐없이 들꽃 씨앗을 뿌렸어요.","봄날, 길가에 예쁜 꽃과 향기 진한 들풀이 피어났어요.","일 년이 지난 여름날, 꽃들은 더욱 만발했어요.","우편집배원은 길가에 작은 묘목을 심으며 먼 훗날을 기약했어요."],"title":"『국어』 154~157쪽 「희망을 만든 우편집배원」(김현태) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
