INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#3','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C3',1,'mc','auto','『국어활동』 59쪽 — 「햇볕 때문에 창가에 둔 책의 색이 ( ) 있어요.」',ARRAY['K2-2-u5-X02','K2-2-u5-X03']::text[],false,'{"seq":3,"concept":"K2-2-u5-C3","difficulty":1,"kind":"mc","stem":"『국어활동』 59쪽 — 「햇볕 때문에 창가에 둔 책의 색이 ( ) 있어요.」","options":[{"t":"바래고","correct":true},{"t":"바라고","mis":"K2-2-u5-X02"},{"t":"적고","mis":"K2-2-u5-X03"}],"explanation":["바래고예요.","국어활동 59쪽 예시 답안이에요.","색이 흐려졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#4','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C4',1,'mc','auto','「준비물 챙기는 것을 깜빡 ( ).」에 알맞은 말은?',ARRAY['K2-2-u5-X05','K2-2-u5-X04']::text[],false,'{"seq":4,"concept":"K2-2-u5-C4","difficulty":1,"kind":"mc","stem":"「준비물 챙기는 것을 깜빡 ( ).」에 알맞은 말은?","options":[{"t":"잊어버렸다","correct":true},{"t":"잃어버렸다","mis":"K2-2-u5-X05"},{"t":"틀렸다","mis":"K2-2-u5-X04"}],"explanation":["잊어버렸다예요.","지도서 212쪽이에요.","깜빡 생각이 안 났어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#5','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C7',1,'mc','auto','「팥죽 할머니와 호랑이」에서 시간을 나타내는 말은?',ARRAY['K2-2-u5-X11']::text[],false,'{"seq":5,"concept":"K2-2-u5-C7","difficulty":1,"kind":"mc","stem":"「팥죽 할머니와 호랑이」에서 시간을 나타내는 말은?","options":[{"t":"밤","correct":true},{"t":"지게","mis":"K2-2-u5-X11"},{"t":"멍석","mis":"K2-2-u5-X11"}],"explanation":["밤이에요.","국어활동 67쪽이에요.","「밤이 되자」예요."],"asset":{"type":"passage","lines":["옛날에 산비탈에서 할머니가 팥밭을 매고 있었어요.","드디어 동짓날이 되었어요. 할머니는 가마솥 가득 팥죽을 쑤었어요.","밤이 되자 호랑이가 할머니 집으로 어슬렁어슬렁 걸어 들어왔어요.","멍석이 마당에서 데굴데굴 구르는 호랑이를 뚜르르 말았어요.","지게가 멍석에 말린 호랑이를 짊어졌어요."],"title":"『국어활동』 66~67쪽 「팥죽 할머니와 호랑이」에서 일어난 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#6','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C8',1,'mc','auto','윤재네 가족이 점심에 한 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":6,"concept":"K2-2-u5-C8","difficulty":1,"kind":"mc","stem":"윤재네 가족이 점심에 한 일은?","options":[{"t":"미리 준비한 도시락을 맛있게 먹었습니다.","correct":true},{"t":"식물원에서 꽃을 구경했습니다.","mis":"K2-2-u5-X13"},{"t":"놀이터에서 놀았습니다.","mis":"K2-2-u5-X13"}],"explanation":["도시락을 먹었어요.","163쪽이에요.","점심이에요."],"asset":{"type":"passage","lines":["오전에는 공원의 놀이터에서 놀았습니다.","오후에는 식물원에서 다양한 꽃을 구경했습니다.","토요일 아침, 윤재네 가족은 공원에 도착했습니다.","점심에는 미리 준비한 도시락을 맛있게 먹었습니다."],"title":"『국어』 163쪽 2번 (차례가 섞여 있어요)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#7','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C1',1,'mc','auto','뜻이 헷갈리는 말을 쓰면 어떤 일이 생길 수 있나요?',ARRAY['K2-2-u5-X07']::text[],false,'{"seq":7,"concept":"K2-2-u5-C1","difficulty":1,"kind":"mc","stem":"뜻이 헷갈리는 말을 쓰면 어떤 일이 생길 수 있나요?","options":[{"t":"듣는 사람이 다르게 알아들어요","correct":true},{"t":"말이 더 짧아져요","mis":"K2-2-u5-X07"},{"t":"아무 일도 없어요","mis":"K2-2-u5-X07"}],"explanation":["다르게 알아들어요.","140쪽 만화예요.","오해가 생겨요."],"asset":{"type":"speech","turns":[{"who":"민재","text":"이 낱말은 뭐야? 가리켜 줘!"},{"who":"지윤","text":"낱말을 가리켜 달라고? 자, 낱말을 가리켰어."},{"who":"민재","text":"뭐 하는 거야? 난 무슨 뜻인지 궁금했는데……."},{"who":"지윤","text":"아! 그러면 낱말의 뜻이 무엇인지 가르쳐 달라고 말해야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
