INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#11','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C10',2,'mc','auto','세나의 하루에서 「밤」에 일어난 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":11,"concept":"K2-2-u5-C10","difficulty":2,"kind":"mc","stem":"세나의 하루에서 「밤」에 일어난 일은?","options":[{"t":"버스에서 아빠에게 이야기하다 잠이 들었어요","correct":true},{"t":"감자를 캤어요","mis":"K2-2-u5-X13"},{"t":"업고 달리기를 했어요","mis":"K2-2-u5-X13"}],"explanation":["버스에서요.","151쪽이에요.","밤이에요."],"asset":{"type":"passage","lines":["일요일 아침, 세나는 아빠와 시골의 「아빠와 함께 추억 만들기」 행사에 갔어요.","가장 먼저 감자밭에서 감자를 조심조심 캤어요.","점심이 되자 캔 감자를 씻어 아궁이에 쪄서 먹었어요.","오후에는 아빠가 아이를 업고 달리는 놀이를 했어요. 모두 응원하자 아빠는 더 빨리 달려 이겼어요.","밤이 되어 돌아오는 버스에서 세나는 「아빠 등에 업히니까 따뜻하고 좋았어요.」라고 말하고 잠이 들었어요."],"title":"『국어』 150~151쪽 「아빠와 함께 추억 만들기」(이규희) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#12','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C8',2,'mc','auto','당나귀가 솜을 싣고 일부러 물에 빠진 일보다 먼저 있었던 일은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":12,"concept":"K2-2-u5-C8","difficulty":2,"kind":"mc","stem":"당나귀가 솜을 싣고 일부러 물에 빠진 일보다 먼저 있었던 일은?","options":[{"t":"소금이 물에 녹아 짐이 가벼워진 일","correct":true},{"t":"솜이 무거워진 일","mis":"K2-2-u5-X13"},{"t":"힘들게 걸어간 일","mis":"K2-2-u5-X13"}],"explanation":["소금 일이 먼저예요.","141쪽이에요.","그래서 꾀를 부렸어요."],"asset":{"type":"passage","lines":["어느 날 소금을 싣고 가던 당나귀는 힘들어 버둥거리다 물속에 빠졌어요.","물에 빠지니 소금이 녹아 짐이 가벼워졌어요. 당나귀는 미소를 지었어요.","다음 날 주인은 솜 자루를 당나귀 등에 실었어요. 당나귀는 꾀를 부려 일부러 물에 빠졌어요.","물을 먹은 솜은 매우 무거워졌어요. 당나귀는 무거운 짐을 싣고 힘들게 걸어갔어요."],"title":"『국어』 141쪽 「제 꾀에 빠진 당나귀」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
