INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#20','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C12',3,'mc','auto','「우리 반에서 정한 활동」 예시 1 — 긍정적인 말로 알맞은 것은?',ARRAY['K2-2-u5-X04','K2-2-u5-X06']::text[],false,'{"seq":20,"concept":"K2-2-u5-C12","difficulty":3,"kind":"mc","stem":"「우리 반에서 정한 활동」 예시 1 — 긍정적인 말로 알맞은 것은?","options":[{"t":"우리 반 친구들은 생각이 달라서 이야기가 재미있어.","correct":true},{"t":"우리 반 친구들은 생각이 틀려서 싫어.","mis":"K2-2-u5-X04"},{"t":"우리 반 친구들은 다 똑같아.","mis":"K2-2-u5-X06"}],"explanation":["다르다로 칭찬해요.","지도서 230쪽이에요.","긍정적인 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#21','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C13',3,'ox','auto','「국물」은 소리 나는 대로 「궁물」이라고 써야 한다.',ARRAY['K2-2-u5-X15']::text[],false,'{"seq":21,"concept":"K2-2-u5-C13","difficulty":3,"kind":"ox","stem":"「국물」은 소리 나는 대로 「궁물」이라고 써야 한다.","answer":"X","reason_options":[{"t":"읽을 때는 [궁물]이지만 쓸 때는 글자대로 「국물」이라고 쓰니까","correct":true},{"t":"소리대로 써야 바른 글이니까","mis":"K2-2-u5-X15"}],"mis":"K2-2-u5-X15","explanation":["글자대로 써요.","164쪽이에요.","소리와 글자가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#22','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C7',3,'mc','auto','「어제 → 오늘 → 내일」처럼 차례대로 놓은 것은?',ARRAY['K2-2-u5-X13']::text[],false,'{"seq":22,"concept":"K2-2-u5-C7","difficulty":3,"kind":"mc","stem":"「어제 → 오늘 → 내일」처럼 차례대로 놓은 것은?","options":[{"t":"작년 → 올해 → 내년","correct":true},{"t":"내년 → 작년 → 올해","mis":"K2-2-u5-X13"},{"t":"올해 → 내년 → 작년","mis":"K2-2-u5-X13"}],"explanation":["작년·올해·내년이에요.","151쪽 도움말이에요.","지난 때부터요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#23','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C7',4,'sa','auto','『국어』 163쪽 — 윤재네 가족이 식물원에서 꽃을 구경한 때를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u5-C7","difficulty":4,"kind":"sa","stem":"『국어』 163쪽 — 윤재네 가족이 식물원에서 꽃을 구경한 때를 두 글자로 쓰세요.","answer":["오후"],"explanation":["오후예요.","163쪽이에요.","마지막 일이에요."],"asset":{"type":"passage","lines":["오전에는 공원의 놀이터에서 놀았습니다.","오후에는 식물원에서 다양한 꽃을 구경했습니다.","토요일 아침, 윤재네 가족은 공원에 도착했습니다.","점심에는 미리 준비한 도시락을 맛있게 먹었습니다."],"title":"『국어』 163쪽 2번 (차례가 섞여 있어요)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#24','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C12',4,'essay','teacher','우리 반 알림판에 붙일 바른 말 알림 글을 쓰세요. 바른 말과 그 뜻을 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u5-C12","difficulty":4,"kind":"essay","stem":"우리 반 알림판에 붙일 바른 말 알림 글을 쓰세요. 바른 말과 그 뜻을 함께 쓰세요.","answer_guide":{"answer":"예: 「가리키다」는 짚어 보이기, 「가르치다」는 알려 주기! 선생님은 우리를 가르치시고, 나는 칠판을 가리켜요. 바르게 써 봐요!","scoring_points":["바른 말과 뜻이 있어요","함께 쓰자고 했어요"]},"explanation":["뜻을 함께요.","160쪽이에요.","읽는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u5_review_d#25','kor',2,2,'u5','','g2_2_kor_u5_review_d','unit_review','K2-2-u5-C8',4,'essay','teacher','시간을 나타내는 말 없이, 「그래서」·「그러자」를 넣어 일이 일어난 차례가 드러나게 세 문장을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u5-C8","difficulty":4,"kind":"essay","stem":"시간을 나타내는 말 없이, 「그래서」·「그러자」를 넣어 일이 일어난 차례가 드러나게 세 문장을 쓰세요.","answer_guide":{"answer":"예: 화분에 물을 주는 것을 잊었다. 그래서 꽃이 시들었다. 그러자 동생이 물을 듬뿍 주었다.","scoring_points":["시간 말이 없어요","일의 앞뒤가 이어져요"]},"explanation":["앞뒤로 차례를 보여요.","지도서 221쪽 오개념이에요.","까닭이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
